<?php declare(strict_types=1);$base=config('app.base_path');$trash=!empty($trash); ?><div class="page-header"><div><h1><?= $trash?'Deleted Stays':'Tourism Stays' ?></h1><p>Hotels, lodges, homestays, guest houses, resorts and other accommodation providers.</p></div><div class="page-actions"><?php if($trash): ?><a class="btn btn-secondary" href="<?= $base ?>/tourism/stays">Active Stays</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/tourism/stays?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/tourism/stays/create">Add Stay</a><?php endif; ?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Stay</th><th>Provider</th><th>Destination</th><th>Location</th><th>Coordinates</th><th>Rooms</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($stays)): ?><tr><td colspan="8"><div class="empty-state">No tourism stays found.</div></td></tr><?php else:foreach($stays as $s): ?><tr><td><strong><?= htmlspecialchars((string)$s['name'],ENT_QUOTES,'UTF-8') ?></strong><br><small><?= htmlspecialchars((string)$s['stay_type'],ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars((string)$s['provider_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)($s['destination_name']??'—'),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(trim((string)($s['city']??'').' / '.(string)($s['district']??''),' /'),ENT_QUOTES,'UTF-8') ?></td><td><?= $s['latitude']!==null?htmlspecialchars($s['latitude'].' , '.$s['longitude'],ENT_QUOTES,'UTF-8'):'Not set' ?></td><td><?= (int)$s['room_count'] ?></td><td><?= htmlspecialchars((string)$s['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($trash): ?><form method="post" action="<?= $base ?>/tourism/stays/<?= (int)$s['id'] ?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/tourism/stays/<?= (int)$s['id'] ?>">View</a> <a class="link-button" href="<?= $base ?>/tourism/stays/<?= (int)$s['id'] ?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach;endif;?></tbody></table></div>
